namespace CompanyPortal.Web.Models;
public sealed record PortalError(int StatusCode,string Title,string Message,string Guidance,string Icon,bool Retry,string? Reference)
{
 public static PortalError Create(int code,string? reference=null)=>code switch {
 400=>new(400,"تعذّر إكمال الطلب","بعض بيانات الطلب غير مكتملة أو غير صحيحة.","تحقق من البيانات وحاول مجددًا.","document",false,reference),
 401=>new(401,"يلزم التحقق من حسابك","لم نتمكن من التحقق من هوية حساب Windows الخاص بك.","تأكد من اتصالك بشبكة المؤسسة واستخدام حساب العمل، ثم أعد المحاولة. إذا استمرت المشكلة، تواصل مع الدعم التقني.","lock",true,reference),
 403=>new(403,"ليس لديك صلاحية الوصول","هذه الصفحة متاحة فقط للحسابات التي لديها الصلاحية المطلوبة.","يمكنك العودة إلى البوابة، أو التواصل مع المسؤول إذا كنت تحتاج إلى هذه الصلاحية.","shield",false,reference),
 404=>new(404,"الصفحة غير موجودة","قد يكون الرابط غير صحيح، أو تم نقل الصفحة أو إزالتها.","تحقق من الرابط أو عد إلى الصفحة الرئيسية للوصول إلى خدمات البوابة.","search",false,reference),
 405=>new(405,"الطلب غير مسموح","لا يمكن فتح هذه الخدمة بهذه الطريقة.","عد إلى البوابة وافتح الخدمة من الزر أو الرابط المخصص لها.","document",false,reference),
 408=>new(408,"انتهت مهلة الطلب","استغرق إرسال الطلب وقتًا أطول من المتوقع.","تحقق من اتصالك بشبكة المؤسسة ثم حاول مجددًا.","clock",true,reference),
 429=>new(429,"يرجى الانتظار قليلًا","وصلت طلبات كثيرة خلال فترة قصيرة.","انتظر قليلًا قبل إعادة المحاولة.","clock",false,reference),
 502=>new(502,"تعذّر الاتصال بالخدمة","لم تستجب إحدى الخدمات المرتبطة بالبوابة بالشكل المتوقع.","حاول مجددًا بعد قليل. إذا استمرت المشكلة، تواصل مع الدعم التقني.","connection",true,reference),
 503=>new(503,"الخدمة غير متاحة مؤقتًا","يتعذّر تقديم هذه الخدمة في الوقت الحالي.","قد تكون الخدمة تحت الصيانة. يرجى المحاولة لاحقًا.","connection",true,reference),
 504=>new(504,"تأخرت استجابة الخدمة","لم تستجب الخدمة المرتبطة بالبوابة في الوقت المحدد.","تحقق من اتصالك ثم أعد المحاولة بعد قليل.","clock",true,reference),
 _=>new(500,"حدث خطأ غير متوقع","تعذّر عرض الصفحة أو إكمال العملية في الوقت الحالي.","حاول مجددًا بعد قليل. يمكنك تزويد الدعم التقني برقم المرجع أدناه للمساعدة في تتبع المشكلة.","connection",true,reference)
 };
}
